local AG=AleeGather
function AG:InitializeInterfaceOptions()local p=CreateFrame("Frame","AleeGatherInterfaceOptions",UIParent);p.name="AleeGather";local t=p:CreateFontString(nil,"OVERLAY","GameFontNormalLarge");t:SetPoint("TOPLEFT",16,-16);t:SetText("AleeGather");local d=p:CreateFontString(nil,"OVERLAY","GameFontHighlightSmall");d:SetPoint("TOPLEFT",16,-48);d:SetWidth(560);d:SetText("Static Classic/TBC nodes from pfQuest; Northrend nodes learned locally.");local b=AG:CreateThemedButton(p,190,26);b:SetPoint("TOPLEFT",16,-88);b:SetText("Open AleeGather Settings");b:SetScript("OnClick",function()AG:ToggleConfig()end);if InterfaceOptions_AddCategory then InterfaceOptions_AddCategory(p)end end
